	@Test
	void canonicalDeclarationBudgetsObjectSortScratchBeforeMutation() {
		FrontierLayout layout = FrontierLayout.of("x");
		FrontierStateKey[] keys = new FrontierStateKey[6];
		long retainedKeyBytes = 0L;
		for (int index = 0; index < keys.length; index++) {
			keys[index] = key(
					new long[] { 1L << index },
					layout,
					new long[] { 1L },
					2L,
					3L,
					4L,
					5L,
					6L,
					0,
					1);
			retainedKeyBytes += keys[index].retainedBytes();
		}

		long baseline;
		try (FrontierStateArena sizing = new FrontierStateArena(64 * 1024L)) {
			baseline = sizing.persistentMetadataBytes();
		}
		long clonedInputBytes = arrayBytes(keys.length, Long.BYTES);
		try (FrontierStateArena arena = new FrontierStateArena(baseline + retainedKeyBytes + clonedInputBytes)) {
			assertThrows(IllegalStateException.class, () -> arena.declareCanonicalStates(keys));
			assertEquals(0, arena.size());
		}
	}

