	@Test
	void canonicalInterningReusesStateAndSeedAcrossPhysicalExploration() {
		FrontierStateKey firstKey = key(
				new long[] { 5L },
				FrontierLayout.of("x"),
				new long[] { 1L },
				2L,
				3L,
				4L,
				5L,
				6L,
				1,
				1);
		FrontierStateKey equivalentKey = key(
				new long[] { 5L },
				FrontierLayout.of("x"),
				new long[] { 1L },
				2L,
				3L,
				4L,
				5L,
				6L,
				1,
				1);
		EvidenceStateSummary summary = EvidenceStateSummary.exact(8.0d);

		try (FrontierStateArena first = new FrontierStateArena(64 * 1024L);
				FrontierStateArena second = new FrontierStateArena(64 * 1024L)) {
			EvidenceStateRef firstReference = first.intern(firstKey, summary);
			EvidenceStateRef repeatedReference = first.intern(equivalentKey, summary);
			EvidenceStateRef rematerializedReference = second.intern(equivalentKey, summary);

			assertEquals(firstReference, repeatedReference);
			assertNotEquals(firstReference, rematerializedReference);
			assertEquals(1, first.size());
			assertEquals(firstKey, first.key(firstReference));
			assertEquals(first.deterministicSeed(firstReference), second.deterministicSeed(rematerializedReference));
			assertThrows(IllegalStateException.class,
					() -> first.intern(equivalentKey, EvidenceStateSummary.exact(9.0d)));
		}
	}

	@Test
	void declaredCanonicalIdsDoNotDependOnPhysicalExplorationOrder() {
		FrontierStateKey firstKey = key(
				new long[] { 1L },
				FrontierLayout.of("x"),
				new long[] { 1L },
				2L,
				3L,
				4L,
				5L,
				6L,
				1,
				1);
		FrontierStateKey secondKey = key(
				new long[] { 2L },
				FrontierLayout.of("y"),
				new long[] { 1L },
				2L,
				3L,
				4L,
				5L,
				6L,
				1,
				1);

		try (FrontierStateArena first = new FrontierStateArena(64 * 1024L);
				FrontierStateArena second = new FrontierStateArena(64 * 1024L)) {
			first.declareCanonicalStates(secondKey, firstKey);
			second.declareCanonicalStates(firstKey, secondKey);

			EvidenceStateRef firstThenSecond = first.intern(firstKey, EvidenceStateSummary.exact(1.0d));
			EvidenceStateRef secondAfterFirst = first.intern(secondKey, EvidenceStateSummary.exact(2.0d));
			EvidenceStateRef secondThenFirst = second.intern(secondKey, EvidenceStateSummary.exact(2.0d));
			EvidenceStateRef firstAfterSecond = second.intern(firstKey, EvidenceStateSummary.exact(1.0d));

			assertEquals(firstThenSecond.stateId(), firstAfterSecond.stateId());
			assertEquals(secondAfterFirst.stateId(), secondThenFirst.stateId());
			assertEquals(2, first.size());
			assertEquals(2, second.size());
			assertThrows(IllegalArgumentException.class,
					() -> first.intern(
							key(new long[] { 4L }, FrontierLayout.of("z"), new long[] { 1L },
									2L, 3L, 4L, 5L, 6L, 1, 1),
							EvidenceStateSummary.exact(3.0d)));
		}
	}

